function slugify(value) {
    return String(value || "")
        .normalize("NFKD")
        .replace(/[\u0300-\u036f]/g, "")
        .toLowerCase()
        .replace(/&/g, " and ")
        .replace(/[^a-z0-9]+/g, " ")
        .trim()
        .replace(/\s+/g, " ");
}
function isFiniteCoord(value) {
    if (value === null || value === undefined || value === "") return false;
    return Number.isFinite(Number(value));
}
function coordOrNull(value) {
    return isFiniteCoord(value) ? Number(value) : null;
}
function centerOfCountry(country) {
    return {
        lat: Number(country?.lat),
        lon: Number(country?.lon)
    };
}
function isZeroCoordinate(lat, lon) {
    return isFiniteCoord(lat) &&
        isFiniteCoord(lon) &&
        Math.abs(Number(lat)) < 0.000001 &&
        Math.abs(Number(lon)) < 0.000001;
}
function coordInBbox(lat, lon, bbox, margin = 0.45) {
    if (!bbox || !isFiniteCoord(lat) || !isFiniteCoord(lon)) return false;
    const [minLon, minLat, maxLon, maxLat] = bbox;
    return (
        Number(lat) >= minLat - margin &&
        Number(lat) <= maxLat + margin &&
        Number(lon) >= minLon - margin &&
        Number(lon) <= maxLon + margin
    );
}
function tryExactLookup(rawValue) {
    const key = slugify(rawValue);
    if (!key) return null;
    if (CITY_OVERRIDES[key]) {
        return { type: "city", ...CITY_OVERRIDES[key] };
    }
    if (CAPITAL_INDEX[key]) {
        return { type: "capital", ...CAPITAL_INDEX[key] };
    }
    if (COUNTRY_ALIAS_INDEX[key]) {
        const code = COUNTRY_ALIAS_INDEX[key];
        return { type: "country", country: code, name: GLOBAL_COUNTRIES[code]?.name || rawValue };
    }
    if (SUBDIVISION_INDEX[key]) {
        const code = SUBDIVISION_INDEX[key];
        return { type: "subdivision", country: code, name: rawValue };
    }
    return null;
}
function tryDemonymLookup(text = "") {
    const haystack = ` ${slugify(text)} `;
    if (!haystack.trim()) return null;
    const demonyms = Object.keys(DEMONYM_TO_COUNTRY).sort((a, b) => b.length - a.length);
    for (const demonym of demonyms) {
        if (!demonym) continue;
        if (haystack.includes(` ${demonym} `)) {
            const code = DEMONYM_TO_COUNTRY[demonym];
            return {
                type: "country",
                country: code,
                name: GLOBAL_COUNTRIES[code]?.name || demonym
            };
        }
    }
    return null;
}
function tryRegionKeywordLookup(text = "") {
    const haystack = ` ${slugify(text)} `;
    if (!haystack.trim()) return null;
    const keys = Object.keys(REGION_KEYWORDS).sort((a, b) => b.length - a.length);
    for (const key of keys) {
        if (!key) continue;
        if (haystack.includes(` ${key} `)) {
            const hit = REGION_KEYWORDS[key];
            return {
                type: "region",
                regionId: hit.regionId,
                name: hit.name
            };
        }
    }
    return null;
}
function tryGroupKeywordLookup(text = "") {
    const haystack = ` ${slugify(text)} `;
    if (!haystack.trim()) return null;
    const keys = Object.keys(GROUP_KEYWORDS).sort((a, b) => b.length - a.length);
    for (const key of keys) {
        if (!key) continue;
        if (haystack.includes(` ${key} `)) {
            const hit = GROUP_KEYWORDS[key];
            return {
                type: "group",
                groupId: hit.groupId,
                name: hit.name
            };
        }
    }
    return null;
}
function scanTextForCountry(text) {
    const haystack = ` ${slugify(text)} `;
    if (!haystack.trim()) return null;
    const aliases = Object.keys(COUNTRY_ALIAS_INDEX).sort((a, b) => b.length - a.length);
    for (const alias of aliases) {
        if (!alias) continue;
        if (haystack.includes(` ${alias} `)) {
            const code = COUNTRY_ALIAS_INDEX[alias];
            return { type: "country", country: code, name: GLOBAL_COUNTRIES[code]?.name || alias };
        }
    }
    const demonymHit = tryDemonymLookup(text);
    if (demonymHit) return demonymHit;
    const capitals = Object.keys(CAPITAL_INDEX).sort((a, b) => b.length - a.length);
    for (const cap of capitals) {
        if (!cap) continue;
        if (haystack.includes(` ${cap} `)) {
            return { type: "capital", ...CAPITAL_INDEX[cap] };
        }
    }
    const regionHit = tryRegionKeywordLookup(text);
    if (regionHit) return regionHit;
    const groupHit = tryGroupKeywordLookup(text);
    if (groupHit) return groupHit;
    return null;
}
export function extractPlaceMatch(event = {}) {
    const priorityFields = [
        event.country,
        event.countryName,
        event.country_code,
        event.iso2,
        event.iso3,
        event.city,
        event.capital,
        event.province,
        event.state,
        event.admin1,
        event.region,
        event.location,
        event.location_label,
        event.impact_label
    ];
    for (const value of priorityFields) {
        const hit = tryExactLookup(value) || tryDemonymLookup(value) || tryRegionKeywordLookup(value) || tryGroupKeywordLookup(value);
        if (hit) return hit;
    }
    const textFields = [
        event.title,
        event.summary,
        event.description,
        event.location_label,
        event.impact_label
    ].filter(Boolean).join(" | ");
    return scanTextForCountry(textFields);
}
export function isMovingTrackEvent(event = {}) {
    const src = slugify(event.source_name || "");
    const category = slugify(event.category || "");
    const sub = slugify(event.subcategory || "");
    const weapon = slugify(event.weapon_type || "");
    const meta = slugify(JSON.stringify(event.metadata || {}));
    if (src.includes("ads b") || src.includes("opensky") || src.includes("ais")) return true;
    if (category === "military" && /fighter|awacs|tanker|carrier|amphibious|cruiser|destroyer|frigate|corvette|submarine|ssbn|ssn|ssk|aip|missile boat|patrol|logistics|minesweeper|transport|recon|isr|naval|aircraft/.test(`${sub} ${weapon} ${meta}`)) {
        return true;
    }
    return false;
}
export function resolveDisplayCoordinates(event = {}) {
    const sourceLat = isFiniteCoord(event.source_lat) ? Number(event.source_lat) : Number(event.lat);
    const sourceLon = isFiniteCoord(event.source_lon) ? Number(event.source_lon) : Number(event.lon);
    const impactLat = isFiniteCoord(event.impact_lat) ? Number(event.impact_lat) : null;
    const impactLon = isFiniteCoord(event.impact_lon) ? Number(event.impact_lon) : null;
    const category = slugify(event.category || "");
    const movingTrack = isMovingTrackEvent(event);
    const place = extractPlaceMatch(event);
    const country = place?.country ? GLOBAL_COUNTRIES[place.country] : null;
    let lat = sourceLat;
    let lon = sourceLon;
    let reason = "raw";
    let mismatch = false;
    let precision = "raw";
    if (!movingTrack && isZeroCoordinate(lat, lon)) {
        lat = null;
        lon = null;
        reason = "invalid_zero_coordinate";
        precision = "missing";
    }
    if (!movingTrack && (place?.type === "country" || place?.type === "subdivision")) {
        lat = null;
        lon = null;
        reason = `${place.type}_unmapped`;
        precision = "missing";
    }
    const impactFirst = ["strike", "alert", "airspace", "thermal", "signal", "seismic", "cyber"].includes(category);
    if (!movingTrack && impactFirst && isFiniteCoord(impactLat) && isFiniteCoord(impactLon)) {
        lat = impactLat;
        lon = impactLon;
        reason = "impact";
        precision = "impact";
    }
    if (!movingTrack && place?.type === "city" && isFiniteCoord(place.lat) && isFiniteCoord(place.lon)) {
        if (!isFiniteCoord(lat) || !isFiniteCoord(lon)) {
            lat = Number(place.lat);
            lon = Number(place.lon);
            reason = "city_exact";
            precision = "city";
        }
    }
    if (!movingTrack && place?.type === "capital" && isFiniteCoord(place.lat) && isFiniteCoord(place.lon)) {
        const inside = country?.bbox ? coordInBbox(lat, lon, country.bbox) : false;
        if (!inside || !isFiniteCoord(lat) || !isFiniteCoord(lon)) {
            mismatch = mismatch || (isFiniteCoord(lat) && isFiniteCoord(lon) && !inside);
            lat = Number(place.lat);
            lon = Number(place.lon);
            reason = "capital_exact";
            precision = "capital";
        }
    }
    if (!movingTrack && country?.bbox) {
        const inside = coordInBbox(lat, lon, country.bbox);
        if (!inside) {
            mismatch = mismatch || (isFiniteCoord(lat) && isFiniteCoord(lon));
            if (isFiniteCoord(impactLat) && isFiniteCoord(impactLon) && coordInBbox(impactLat, impactLon, country.bbox)) {
                lat = impactLat;
                lon = impactLon;
                reason = "impact_in_country";
                precision = "impact";
            } else if (place?.type !== "country" && place?.type !== "subdivision") {
                const center = centerOfCountry(country);
                lat = center.lat;
                lon = center.lon;
                reason = place?.type === "subdivision" ? "subdivision_to_country_center" : "country_center";
                precision = "country";
            } else {
                lat = null;
                lon = null;
                reason = `${place.type}_unmapped`;
                precision = "missing";
            }
        }
    }
    if (!isFiniteCoord(lat) || !isFiniteCoord(lon)) {
        if (isFiniteCoord(impactLat) && isFiniteCoord(impactLon)) {
            lat = impactLat;
            lon = impactLon;
            reason = "impact_fallback";
            precision = "impact";
        } else if (place?.type === "city" && isFiniteCoord(place.lat) && isFiniteCoord(place.lon)) {
            lat = Number(place.lat);
            lon = Number(place.lon);
            reason = "city_fallback";
            precision = "city";
        } else if (place?.type === "capital" && isFiniteCoord(place.lat) && isFiniteCoord(place.lon)) {
            lat = Number(place.lat);
            lon = Number(place.lon);
            reason = "capital_fallback";
            precision = "capital";
        } else if (country && place?.type !== "country" && place?.type !== "subdivision") {
            const center = centerOfCountry(country);
            lat = center.lat;
            lon = center.lon;
            reason = "country_fallback";
            precision = "country";
        }
    }
    return {
        lat: coordOrNull(lat),
        lon: coordOrNull(lon),
        reason,
        mismatch,
        precision,
        placeType: place?.type || "",
        countryCode: place?.country || "",
        countryName: country?.name || "",
        regionId: place?.regionId || "",
        groupId: place?.groupId || "",
        resolvedPlaceName: place?.name || country?.name || ""
    };
}
export function eventMatchesBounds(event = {}, bounds) {
    if (!bounds) return true;
    const lat = Object.prototype.hasOwnProperty.call(event, "display_lat")
        ? coordOrNull(event.display_lat)
        : coordOrNull(event.lat);
    const lon = Object.prototype.hasOwnProperty.call(event, "display_lon")
        ? coordOrNull(event.display_lon)
        : coordOrNull(event.lon);
    if (!isFiniteCoord(lat) || !isFiniteCoord(lon)) return false;
    return (
        lat >= bounds.minLat &&
        lat <= bounds.maxLat &&
        lon >= bounds.minLon &&
        lon <= bounds.maxLon
    );
}
